import pathlib,json,subprocess,tempfile,os,shutil
def retire(zone_file,manifest_file,outdir):
    source=pathlib.Path(zone_file).resolve();target=pathlib.Path(outdir).resolve()
    if target.exists():raise FileExistsError(target)
    work=pathlib.Path(tempfile.mkdtemp(prefix='.retire-',dir=target.parent))
    def canonical(path):
        dump=work/'canonical.tmp'
        try:
            subprocess.run(['named-checkzone','-i','none','-D','-o',str(dump),'example.test',str(path)],capture_output=True,text=True,check=True,timeout=3)
            return [line.split(None,4) for line in dump.read_text().splitlines() if line.strip() and not line.startswith(';')]
        finally:
            if dump.exists():dump.unlink()
    def write(path,rows):path.write_text(''.join('\t'.join(row)+'\n' for row in rows))
    try:
        rows=canonical(source)
        if any(row[3] in ('DNSKEY','RRSIG','NSEC','NSEC3') for row in rows):raise ValueError('signed zone requires a signing workflow')
        plan=json.loads(pathlib.Path(manifest_file).read_text())
        if not isinstance(plan,list) or not plan:raise ValueError('non-empty retirement plan required')
        removals={};cnames={r[0].lower():r[4].lower() for r in rows if r[3]=='CNAME'}
        for item in plan:
            if not isinstance(item,dict):raise ValueError('invalid plan item')
            name=item.get('name');expected=item.get('expected_target');ticket=item.get('ticket')
            if not isinstance(name,str) or not name.lower().endswith('.example.test.') or not isinstance(expected,str):raise ValueError('invalid name/target')
            name=name.lower();expected=expected.lower()
            if name in removals or cnames.get(name)!=expected:raise ValueError('duplicate or changed CNAME')
            if item.get('provider_state')!='released' or not isinstance(ticket,str) or not ticket.strip():raise ValueError('release evidence and ticket required')
            removals[name]={'name':name,'target':expected,'ticket':ticket}
        for name,destination in cnames.items():
            if name not in removals and destination in removals:raise ValueError('retained alias depends on retired name')
        soa=[r for r in rows if r[3]=='SOA' and r[0].lower()=='example.test.']
        if len(soa)!=1:raise ValueError('single apex SOA required')
        serial=int(soa[0][4].split()[2]);forward_serial=(serial+1)%2**32;rollback_serial=(serial+2)%2**32
        def version(records,new_serial):
            output=[]
            for r in records:
                copy=list(r)
                if copy[3]=='SOA':
                    fields=copy[4].split();fields[2]=str(new_serial);copy[4]=' '.join(fields)
                output.append(copy)
            return output
        forward=[r for r in rows if not (r[3]=='CNAME' and r[0].lower() in removals)]
        write(work/'forward.zone',version(forward,forward_serial))
        write(work/'rollback.zone',version(rows,rollback_serial))
        canonical(work/'forward.zone');canonical(work/'rollback.zone')
        report={'old_serial':serial,'forward_serial':forward_serial,'rollback_serial':rollback_serial,'removed':[removals[k] for k in sorted(removals)]}
        (work/'changes.json').write_text(json.dumps(report,sort_keys=True)+'\n')
        os.rename(work,target)
        return report
    finally:
        if work.exists():shutil.rmtree(work)
